package com.graduation.club.domain; import com.graduation.club.auth.AuthService; import com.graduation.club.common.ApiException; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/memberships") public class MembershipController{ private final MembershipRepository repo;private final ClubRepository clubs;private final AuthService auth; public MembershipController(MembershipRepository r,ClubRepository c,AuthService a){repo=r;clubs=c;auth=a;} public record Apply(@jakarta.validation.constraints.NotNull @jakarta.validation.constraints.Positive Long clubId,@jakarta.validation.constraints.Size(max=1000) String motivation){}
@PostMapping("/apply") public Membership apply(@jakarta.validation.Valid @RequestBody Apply x){var u=auth.currentUser();clubs.findById(x.clubId()).orElseThrow(()->ApiException.notFound("社团不存在"));var existing=repo.findByClubIdAndUserId(x.clubId(),u.getId());if(existing.isPresent()&&List.of("PENDING","APPROVED").contains(existing.get().getStatus()))throw ApiException.badRequest("已申请或已加入该社团");var m=existing.orElseGet(Membership::new);m.setClubId(x.clubId());m.setUserId(u.getId());m.setMotivation(x.motivation());m.setStatus("PENDING");return repo.save(m);}
@GetMapping public List<Membership> mine(){var u=auth.currentUser();return "ADMIN".equals(u.getRole())?repo.findAll(org.springframework.data.domain.PageRequest.of(0,200,org.springframework.data.domain.Sort.by(org.springframework.data.domain.Sort.Direction.DESC,"id"))).getContent():repo.findTop200ByUserIdOrderByIdDesc(u.getId());}
@PatchMapping("/{id}/status") @PreAuthorize("hasRole('ADMIN')") public Membership status(@PathVariable Long id,@RequestParam String value){if(!List.of("APPROVED","REJECTED").contains(value))throw ApiException.badRequest("状态非法");var m=repo.findById(id).orElseThrow(()->ApiException.notFound("申请不存在"));m.setStatus(value);return repo.save(m);} }
